def compute(vars):
    costs_million = vars["v1"]
    notes_billion = vars["v2"]
    notes_million = notes_billion * 1000

    if notes_million == 0:
        return None

    percentage = costs_million / notes_million * 100
    return {
        "value": percentage,
        "trace": {
            "costs_million": costs_million,
            "notes_billion": notes_billion,
            "notes_million": notes_million,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
